/// <summary>
///CB871_CB872 Sales returns
/// Batch service class for return order delivery notes posting
/// </summary>
class METDeliveryNotePostingTaskService extends METSysOperationTaskService
{
    guid  topPickingProcessId;

    SalesReturnItemNum returnOrderNum;
    METReturnOrderDeliveryNoteHeader returnOrderHeader;


}

Method.Source:
//// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METInventJournalPostingContract</c>.
/// </param>
public void process(METDeliveryNotePostingContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>
/// Process the batch tasks.
/// </summary>
/// <param name = "_readPast">Read past table setting.</param>
public void processTask(boolean _readPast)
{
    while (this.getReturnOrderIdFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (this.returnOrderNum && returnOrderHeader.IntegrationStatus == METIntegrationStatus::None)
            {
                ttsbegin;
                if (returnOrderHeader)
                {
                    this.createAndPostDeliveryNote();
                    returnOrderHeader.reread();
                    this.updateDeliveryNotePostingStatus(METIntegrationStatus::Acknowledged);
                }
                ttscommit;
            }
        }
        catch (Exception::Error)
        {
            str errormessage;
            errormessage = infolog.text(infologLine());
            errormessage = infolog.text(infologLine()-1);
            errormessage = errormessage + METconstants::space + infolog.text(infologLine());


            // Catch any exception so that any one error won't bring down
            /// the entire process of sales order pallet rounding but will still capture and show the error.
            Global::exceptionTextFallThrough();
            // Send header error to telemetry from here
            // Update header error
            this.updateDeliveryNotePostingStatus(METIntegrationStatus::Error);
            this.sendDeliveryNotesHeaderInformationToAppinsights(errormessage);
        }
    }
}

/// <summary>
/// Send delivery notes posting  error  to app insights
/// </summary>
/// <param name = "errorMessage">error message</param>
protected void sendDeliveryNotesHeaderInformationToAppinsights(Notes errorMessage)
{
    Notes errMsg = errorMessage;
    TableId tableId = TableNum(METReturnOrderDeliveryNoteHeader);
    DictFieldGroup dictFieldGrp = new DictFieldGroup(tableId, METConstants::METReference);
    int counter, fieldId;

    METTelemetryDeliveryNotePostLogging metDeliveryNotesPostLogging = METTelemetryDeliveryNotePostLogging::construct(errMsg);
    // If table is having table group METReference then check all the fields and assign those fields as custom dimensions
    if (dictFieldGrp)
    {
        for (counter = 1; counter <= dictFieldGrp.numberOfFields(); counter++)
        {
            fieldId = dictFieldGrp.field(counter);

            DictField dictField = new DictField(tableId, fieldId);
            if (returnOrderHeader.(fieldId))
            {
                errMsg += strFmt("@MET:Multiplestrmt",dictField.label(), any2str(returnOrderHeader.(fieldId)));
                //Reference Added as custom dimension
                metDeliveryNotesPostLogging.addRuntimeProperty(dictField.label(), any2str(returnOrderHeader.(fieldId)));
            }
        }
    }

    metDeliveryNotesPostLogging.errmsg = errMsg;
    metDeliveryNotesPostLogging.processEvent(METApplicationInsightsEventNames::DeliveryNotePostLog);

}

/// <summary>
/// Initializes the object.
/// </summary>
protected void initialise()
{
    super();

    // get the topPickingProcessId from the contract
    METDeliveryNotePostingContract contract = dataContract as METDeliveryNotePostingContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Check sales parm line with dallas line
/// </summary>
/// <param name = "_salesParmLine">_salesParmLine</param>
/// <returns>Validation message</returns>
private str lineValidationCheckForDallas(SalesParmLine  _salesParmLine)
{
    str errMsg;
    METReturnOrderDeliveryNoteLines metReturnOrderLines;
    if (_salesParmLine.PdsCWDeliverNow)
    {
        select firstonly metReturnOrderLines
            where metReturnOrderLines.LineNumber == _salesParmLine.LineNum
            && metReturnOrderLines.CWUpdate == _salesParmLine.PdsCWDeliverNow
            && metReturnOrderLines.ItemNumber == _salesParmLine.ItemId
            && metReturnOrderLines.IntegrationStatus == METIntegrationStatus::None;
    }
    else
    {
        select firstonly metReturnOrderLines
            where metReturnOrderLines.LineNumber == _salesParmLine.LineNum
            && metReturnOrderLines.Quantity   == _salesParmLine.DeliverNow
            && metReturnOrderLines.ItemNumber == _salesParmLine.ItemId
            && metReturnOrderLines.IntegrationStatus == METIntegrationStatus::None;
    }

    if (!metReturnOrderLines)
    {
        errMsg = strFmt("@MET:ItemNotFoundDallas",_salesParmLine.LineNum, _salesParmLine.ItemId, _salesParmLine.DeliverNow);
    }
    return errMsg;
}

///Create and post return order delivery notes
private void createAndPostDeliveryNote()
{
    str errMsg;
    SalesFormLetter_PackingSlip salesFormLetter_PackingSlip;
    salesFormletterParmData salesFormLetterParmData;

    SalesParmTable salesParmTable;
    SalesParmLine salesParmLine;
    salesLine salesLine;
    salesParmUpdate         salesParmUpdate;
    SalesTable salestable = SalesTable::findReturnItemNum(returnOrderNum);
    CustPackingSlipJour custPackingSlipJour;
    TransDate   PackingSlipDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    ;

    if (salestable && salestable.SalesStatus == SalesStatus::Backorder)
    {
        ttsbegin;
        salesFormLetterParmData = salesFormletterParmData::newData(DocumentStatus::PackingSlip, VersioningUpdateType::Initial);

        salesFormLetterParmData.parmOnlyCreateParmUpdate(true);
        salesFormLetterParmData.parmSpecQty(SalesUpdate::All);
        salesFormLetterParmData.createData(false);
        salesParmUpdate = salesFormLetterParmData.parmParmUpdate();

        salesParmTable.clear();
        salesParmTable.TransDate                = PackingSlipDate;
        salesParmTable.Ordering                 = DocumentStatus::PackingSlip;
        salesParmTable.ParmJobStatus            = ParmJobStatus::Waiting;
        salesParmTable.salesId                  = salesTable.salesId;

        salesParmTable.salesName                = salesTable.salesName;
        salesParmTable.DeliveryName             = salesTable.DeliveryName;
        salesParmTable.DeliveryPostalAddress    = salesTable.DeliveryPostalAddress;
        salesParmTable.CustAccount              = salesTable.CustAccount;
        salesParmTable.CurrencyCode             = salesTable.CurrencyCode;
        salesParmTable.InvoiceAccount           = salesTable.InvoiceAccount;
        salesParmTable.ParmId                   = salesParmUpdate.ParmId;
        salesParmTable.ReturnPackingSlipId      = returnOrderHeader.CustDeliveryNote;
        salesParmTable.DocumentDate             = returnOrderHeader.DocumentDate;
        salesParmTable.insert();

        while select salesLine where salesLine.SalesId == salestable.SalesId
        {
            salesParmLine.InitFromsalesLine(salesLine);
            salesParmLine.PdsCWDeliverNow = salesLine.PdsCWExpectedRetQty;
            salesParmLine.DeliverNow    = salesLine.SalesQty;
            salesParmLine.ParmId        = salesParmTable.ParmId;
            salesParmLine.TableRefId    = salesParmTable.TableRefId;
            salesParmLine.setQty(DocumentStatus::PackingSlip, false, true);
            salesParmLine.setLineAmount(salesLine);

            errMsg = errMsg + this.lineValidationCheckForDallas(salesParmLine);
            if (!errMsg)
            {
                salesParmLine.insert();
            }

        }
        if (errMsg)
        {
            throw error(errMsg);
        }

        salesFormLetter_PackingSlip = salesFormLetter::construct(DocumentStatus::PackingSlip);
        salesFormLetter_PackingSlip.transDate(PackingSlipDate);
        salesFormLetter_PackingSlip.proforma(false);
        salesFormLetter_PackingSlip.specQty(salesUpdate::All);
        salesFormLetter_PackingSlip.salesTable(salesTable);
        salesFormLetter_PackingSlip.parmId(salesParmTable.ParmId);
        salesFormLetter_PackingSlip.salesParmUpdate(salesFormLetterParmData.parmParmUpdate());
        salesFormLetter_PackingSlip.run();

        if (salesFormLetter_PackingSlip.parmJournalRecord().TableId == tableNum(custPackingSlipJour))
        {
            custPackingSlipJour = salesFormLetter_PackingSlip.parmJournalRecord();
            info(custPackingSlipJour.PackingSlipId);
        }
        ttscommit;
    }

}

/// <summary>
/// Get return sales order RMA id to substitute from the top picking queue <c>METReturnOrderPostingQueue</c>
/// </summary>
/// <param name = "_processId">Guid created and added in the contract <c>METDeliveryNotePostingContract</c></param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>Get sales order id to substitute</returns>
private InventJournalId getReturnOrderIdFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount
    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    METReturnOrderPostingQueue postQueue;
    int backOffWait;

    postQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock ReturnOrderNum
        from postQueue
        where postQueue.ProcessId == _processId;

        if (postQueue.RecId)
        {
            this.returnOrderNum = postQueue.ReturnOrderNum;
            returnOrderHeader = METReturnOrderDeliveryNoteHeader::find(this.returnOrderNum, true);
            postQueue.delete();
        }
        else
        {
            this.returnOrderNum = METConstants::emptyString;
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return this.returnOrderNum;
}

/// <summary>
/// Update dallas return sales order header processing status
/// </summary>
/// <param name = "_metIntegrationStatus">Sales order header additional fields</param>
protected void updateDeliveryNotePostingStatus(METIntegrationStatus _metIntegrationStatus)
{
    METReturnOrderDeliveryNoteLines metReturnOrderLinesUpd;
    if (returnOrderHeader)
    {
        ttsbegin;
        //this.skipInventJournalTableEvents();
        returnOrderHeader.IntegrationStatus = _metIntegrationStatus;
        returnOrderHeader.update();

        update_recordset metReturnOrderLinesUpd
            setting IntegrationStatus = _metIntegrationStatus
            where metReturnOrderLinesUpd.ReturnOrderNum == returnOrderNum;

        ttscommit;
    }
}
